From fad8bf56a86153b8f3ae9004d0d6e5b0dbe6161e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:08:16 +0100
Subject: [PATCH] libtaskmanager: match windows to the desktop file of their
 systemd unit

Apps whose desktop file starts them through a wrapper script showed a
generic icon and pinned a broken launcher. Also match the window by the
app-<id> systemd unit it runs in, when only shells run there with it.

BUG: 403666
---
 libtaskmanager/tasktools.cpp | 74 ++++++++++++++++++++++++++++++++++++
 libtaskmanager/tasktools.h   |  6 +++
 2 files changed, 80 insertions(+)

diff --git a/libtaskmanager/tasktools.cpp b/libtaskmanager/tasktools.cpp
index 67fc843756..90e088af31 100644
--- a/libtaskmanager/tasktools.cpp
+++ b/libtaskmanager/tasktools.cpp
@@ -216,6 +216,11 @@ KService::Ptr serviceFromMetadata(const QString &appId, quint32 pid, const QStri
         return services.first();
     }

+    services = servicesFromCGroup(pid);
+    if (!services.isEmpty()) {
+        return services.first();
+    }
+
     // Ok, absolute *last* chance, try matching via pid
     services = servicesFromPid(pid);

@@ -269,6 +274,75 @@ KService::List servicesFromEnvironment(quint32 pid)
     return {};
 }

+KService::List servicesFromCGroup(quint32 pid)
+{
+    if (pid == 0) {
+        return {};
+    }
+
+    QFile cgroupFile(QStringLiteral("/proc/%1/cgroup").arg(QString::number(pid)));
+    if (!cgroupFile.open(QIODevice::ReadOnly | QIODevice::Text)) {
+        return {};
+    }
+
+    QString cgroup;
+    for (const QByteArray &line : cgroupFile.readAll().split('\n')) {
+        if (line.startsWith("0::")) {
+            cgroup = QString::fromUtf8(line.sliced(3));
+            break;
+        }
+    }
+
+    // Apps launched from a desktop file run in a unit named after it, like
+    // app-<id>@<random>.service or app-<launcher>-<id>-<random>.scope.
+    // See https://systemd.io/DESKTOP_ENVIRONMENTS/
+    const QString unit = cgroup.section(u'/', -1);
+    if (!unit.startsWith(QLatin1String("app-"))) {
+        return {};
+    }
+
+    QString appId;
+    if (unit.endsWith(QLatin1String(".service"))) {
+        appId = unit.chopped(strlen(".service")).section(u'@', 0, 0);
+    } else if (unit.endsWith(QLatin1String(".scope"))) {
+        appId = unit.chopped(strlen(".scope")).section(u'-', 0, -2);
+    } else {
+        return {};
+    }
+
+    // Drop "app-" and the optional launcher, '-' in the id itself is escaped.
+    appId = appId.section(u'-', -1);
+    appId = QString::fromUtf8(QByteArray::fromPercentEncoding(appId.toUtf8().replace("\\x", "%")));
+
+    const KService::Ptr service = KService::serviceByStorageId(appId + QLatin1String(".desktop"));
+    if (!service) {
+        return {};
+    }
+
+    // Only trust the unit when the window's process is the only thing running in it
+    // besides shells, i.e. the app was started through a wrapper script. Other windows
+    // can belong to apps started by the launched app, e.g. games started by Steam.
+    QFile procsFile(QStringLiteral("/sys/fs/cgroup%1/cgroup.procs").arg(cgroup));
+    if (!procsFile.open(QIODevice::ReadOnly | QIODevice::Text)) {
+        return {};
+    }
+
+    const QStringList shells = {u"sh"_s, u"bash"_s, u"dash"_s, u"zsh"_s};
+    for (const QByteArray &line : procsFile.readAll().split('\n')) {
+        const quint32 otherPid = line.toUInt();
+        if (otherPid == 0 || otherPid == pid) {
+            continue;
+        }
+
+        const QString exe = QFileInfo(QStringLiteral("/proc/%1/exe").arg(QString::number(otherPid))).symLinkTarget();
+        if (!shells.contains(QFileInfo(exe).fileName())) {
+            return {};
+        }
+    }
+
+    return {service};
+}
+
 KService::List servicesFromPid(quint32 pid)
 {
     auto proc = KProcessList::processInfo(pid);
diff --git a/libtaskmanager/tasktools.h b/libtaskmanager/tasktools.h
index ae61e25b37..f68f55714d 100644
--- a/libtaskmanager/tasktools.h
+++ b/libtaskmanager/tasktools.h
@@ -83,6 +83,12 @@ serviceFromMetadata(const QString &appId, quint32 pid, const QString &xWindowsWM
 */
 KService::List servicesFromEnvironment(quint32 pid);

+/**
+ * Tries to map a given application to a desktop file
+ * by looking at the systemd unit it was launched in.
+ */
+KService::List servicesFromCGroup(quint32 pid);
